async function auth(){const status=await api('status');$('#app').innerHTML=`<div class="auth"><div class="brand">Ghi Danh</div><p class="muted">Điều hành trung tâm tuyển sinh lái xe</p><h2>${status.setup?'Tạo tài khoản quản trị đầu tiên':'Đăng nhập'}</h2><form id="auth">${status.setup?'<label>Họ tên quản trị viên</label><input name="name" required>':''}<label>Tên đăng nhập</label><input name="username" required autocomplete="username"><label>Mật khẩu ${status.setup?'(ít nhất 10 ký tự)':''}</label><input name="password" type="password" required minlength="${status.setup?10:1}" autocomplete="${status.setup?'new-password':'current-password'}"><p class="error" id="auth-error"></p><button>${status.setup?'Tạo tài khoản':'Đăng nhập'}</button></form><p class="login-note">Dữ liệu lưu trên máy đang chạy ứng dụng. Không có mật khẩu mặc định.</p></div>`;$('#auth').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));if(status.setup)await api('setup',data);user=await api('login',data);await reload()}catch(e){$('#auth-error').textContent=e.message}}}
