 content=`<div class="cards">${card('Hồ sơ đang quản lý',active.length)}${card('Chốt & đã cọc',won.length)}${card('Chờ trường xác nhận',pending.length)}${card('Công việc chưa xong',state.tasks.filter(t=>t.status!=='done').length)}</div>`;
 if(fin()){const f=state.financialSummary;content+=`<section class="fund-highlight"><div class="eyebrow">QUỸ CÒN LẠI SAU CHI PHÍ VÀ NỘP TRƯỜNG</div><strong>${money(state.fund.remaining)}</strong><p>Vốn góp ${money(state.fund.capital)} + thực thu học viên ${money(f.received)} − chi vận hành/đầu tư ${money(f.operatingPaid)} − chi Anh Việt ${money(f.vietPaid)} − chi Anh Hưng ${money(f.hungPaid)} − đã nộp trường ${money(f.schoolPaid)} − hoàn tiền ${money(f.refunds)}.</p><p class="tiny">Quỹ theo số liệu đã ghi nhận. Khoản học viên chưa đóng ${money(f.studentDebt)} chưa cộng vào quỹ; nợ trường ${money(f.schoolDebt)} chưa thanh toán được theo dõi riêng.</p></section><div class="cards">${card('Tổng học phí',money(f.totalTuition))}${card('Đã thu học viên',money(f.received),'Bao gồm lịch sử trong file, không phụ thuộc trạng thái hồ sơ')}${card('Học viên còn phải đóng',money(f.studentDebt))}${card('Đã trả trường',money(f.schoolPaid))}${card('Chi phí vận hành & đầu tư',money(f.operatingPaid),'T8 + T9 + T10 và phát sinh mới')}${card('Chi Anh Việt',money(f.vietPaid))}${card('Chi Anh Hưng',money(f.hungPaid))}${card('Tổng tiền đã chi',money(f.totalSpent),'Anh Việt + Anh Hưng + trường + vận hành + hoàn tiền')}${card('Còn nợ trường',money(f.schoolDebt))}${card('Vốn góp ban đầu',money(state.fund.capital),'Theo nguồn vốn trong file')}${card('Quỹ còn lại theo sổ',money(state.fund.remaining),'Vốn góp + thu học viên − tổng đã chi')}</div><div class="notice">Số gốc từ file được đối soát với giao dịch đã nhập để tránh cộng lặp khi hoàn thiện hồ sơ. ${f.matchedReceipts} khoản thu và ${f.matchedExpenses} khoản chi trùng dữ liệu nguồn đã được loại khỏi phần cộng thêm.</div>`}

