function options(map,value){return Object.entries(map).map(([k,v])=>`<option value="${esc(k)}" ${String(value)===k?'selected':''}>${esc(v)}</option>`).join('')}
function staffOptions(){return Object.fromEntries(state.staff.map(s=>[s.id,`${s.name} (${roles[s.role]})`]))}
function leadOptions(){return Object.fromEntries(buildLeadDirectory(state.leads,state.importDrafts).map(l=>[l.id,`${l.name} • ${l.phone}`]))}
function field(name,label,type='text',opts=null,required=false){return {name,label,type,opts,required}}
function edit(title,fields,record,save){
 $('#modal-title').textContent=title;$('#form-error').textContent='';$('#fields').innerHTML=`<div class="grid">${fields.map(f=>{const v=record[f.name]??'';return `<div class="${f.type==='textarea'?'full':''}"><label>${esc(f.label)}</label>${f.opts?`<select name="${f.name}" ${f.required?'required':''}><option value="">Chọn…</option>${options(f.opts,v)}</select>`:f.type==='textarea'?`<textarea name="${f.name}">${esc(v)}</textarea>`:`<input name="${f.name}" type="${f.type}" value="${esc(v)}" ${f.type==='number'?'min="0" step="1"':''} ${f.required?'required':''}>`}</div>`}).join('')}</div>`;
 $('#editor').onsubmit=async e=>{e.preventDefault();const data={...record,...Object.fromEntries(new FormData(e.target))};for(const f of fields)if(f.type==='number')data[f.name]=Number(data[f.name]||0);const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{await save(data);$('#modal').close();toast('Đã lưu');await reload()}catch(e){$('#form-error').textContent=e.message}finally{button.disabled=false}};$('#modal').showModal();
}
