const importColumns={notes:'Ghi chú học vụ',code:'Mã học viên',name:'Họ tên',cccd:'Số CCCD',license:'Hạng / gói',phone:'Số điện thoại',documents:'Hồ sơ đủ/thiếu',course:'Khóa',stage:'Tiến độ học',tuition:'Học phí',ownerName:'Người phụ trách',source:'Nguồn data',school:'Trường',balance:'Còn phải thu',amount1:'Thu lần 1',date1:'Ngày thu lần 1',amount2:'Thu lần 2',date2:'Ngày thu lần 2',amount3:'Thu lần 3',date3:'Ngày thu lần 3',amount4:'Thu lần 4',date4:'Ngày thu lần 4'};
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().replace(/[^a-z0-9]/g,'');
let importConfig={year:Number(today().slice(0,4)),source:'',owner:'',school:'',defaultDate:''};
function columnGuess(headers){
 const aliases={code:['mahocvien','mahv'],name:['hoten','hovaten','tenhocvien'],cccd:['cccd','socccd','socancuoc'],license:['hang','hangbang','hanghoc','loaibang'],phone:['sdt','dienthoai','sodienthoai'],documents:['hoso','tinhtranghoso'],course:['khoa','khoahoc'],stage:['tiendo','tiendohoc','hanhtrinhhoc'],tuition:['hocphi','tonghocphi'],ownerName:['nguoiphutrach','sale','nhanvien','tuvien','tuvanvien'],source:['nguon','nguondata'],school:['truong','truonglienket'],balance:['conlai','conno','conphaithu'],amount1:['thulan1','donglan1','lan1'],amount2:['thulan2','donglan2','lan2'],amount3:['thulan3','donglan3','lan3'],amount4:['thulan4','donglan4','lan4'],date1:['ngaythulan1','ngaylan1'],date2:['ngaythulan2','ngaylan2'],date3:['ngaythulan3','ngaylan3'],date4:['ngaythulan4','ngaylan4']};
 return Object.fromEntries(Object.keys(importColumns).map(k=>{const index=headers.findIndex(h=>[norm(importColumns[k]),...(aliases[k]||[])].includes(norm(h)));return[k,index<0?'':index]}));
}
function importView(){
 let html=`<div class="notice">Nhập .xlsx, .csv hoặc .tsv, tối đa 6 MB và 1.000 hồ sơ/lần. File được xử lý tại máy chạy ứng dụng. Không tải lên dịch vụ bên ngoài. Chưa nhập dữ liệu cho đến khi xác nhận. CCCD/điện thoại nên để kiểu Text trong Excel; không dùng ô công thức.</div><div class="toolbar">${btn('import-hungthinh','Nạp 34 hồ sơ từ bảng Hưng Thịnh')}${btn('import-template','Tải mẫu CSV','',true)}<input id="import-file" type="file" accept=".xlsx,.csv,.tsv"><span id="import-loading" class="muted"></span></div>`;
 if(importFile){const sheet=importFile.sheets[importSheet],headers=sheet.preview[importHeader]||[];
 html+=panel('1. Chọn sheet và dòng tiêu đề',`<div class="grid"><div><label>File</label><p>${esc(importFile.name)}</p><label>Sheet</label><select id="import-sheet">${options(Object.fromEntries(importFile.sheets.map((s,i)=>[i,`${s.name} (${s.count} dòng)`])),importSheet)}</select></div><div><label>Dòng tiêu đề (tính từ 1)</label><input id="import-header" type="number" min="1" max="40" value="${importHeader+1}"><label>Năm cho ngày dạng 10/8</label><input id="import-year" type="number" min="2000" max="2100" value="${importConfig.year}"></div></div>`);
 html+=panel('2. Ghép cột Excel với dữ liệu hệ thống',`<p class="muted">Kiểm tra từng cột, đặc biệt các cặp số tiền / ngày thu. Cột không có trong file để “Không có”.</p>`+table(['Thông tin','Cột trong file'],Object.entries(importColumns).map(([key,label])=>[label,`<select data-map="${key}"><option value="">Không có</option>${options(Object.fromEntries(headers.map((h,i)=>[i,`${i+1}. ${typeof h==='object'?'Ô lỗi':h||'(trống)'}`])),importMapping[key])}</select>`])));
 html+=panel('3. Bổ sung thông tin chung nếu file chưa có',`<div class="grid"><div><label>Nguồn data cho dòng chưa có nguồn</label><select id="import-source"><option value="">Chưa xác định — giữ chờ bổ sung</option>${options({personal:'Cá nhân',company:'Công ty'},importConfig.source)}</select></div><div><label>Người phụ trách (chọn sẽ áp dụng toàn bộ file)</label><select id="import-owner"><option value="">Đối chiếu tên người phụ trách trong file</option>${options(Object.fromEntries(state.staff.filter(s=>['sale','manager','collaborator'].includes(s.role)).map(s=>[s.id,s.name])),importConfig.owner)}</select></div><div><label>Trường mặc định nếu file không có</label><input id="import-school" value="${esc(importConfig.school)}"></div><div><label>Ngày ghi nhận nếu không có khoản thu</label><input id="import-date" type="date" value="${esc(importConfig.defaultDate)}"></div></div><p class="muted">Các khoản thu lịch sử được nhập vào sổ thu học viên, không phải tiền trả trường. B1/B2 dùng quy ước gói B tự động/B số cơ khí; kiểm tra trước khi xác nhận.</p>${btn('import-preview','Xem trước và kiểm tra')}`);
 }
 if(importJob)html+=panel('4. Kết quả xem trước',`<div class="notice">${importJob.valid} dòng hợp lệ · ${importJob.pending} dòng chờ bổ sung. Xác nhận sẽ nhập dòng hợp lệ và lưu các dòng lỗi riêng; không ghi đè học viên đã có.</div>`+table(['Dòng','Mã','Học viên','Phụ trách','Học phí','Đã thu','Kết quả'],importJob.rows.map(r=>[r.row,esc(r.lead.externalCode),esc(r.lead.name),esc(staffName(r.lead.owner)),money(r.lead.tuition),money(r.payments.reduce((s,p)=>s+p.amount,0)),r.errors.length?`<span class="error">${r.errors.map(esc).join('<br>')}</span>`:tag('Sẵn sàng nhập')]))+`<div class="toolbar">${btn('import-commit','Xác nhận nhập và lưu dòng chờ')}</div>`);
 if(state.hungthinhSource)html+=panel('Nguồn dữ liệu Hưng Thịnh đã nạp',`<p>${state.hungthinhSource.students} hồ sơ, chụp lúc ${esc(state.hungthinhSource.capturedAt)}. Không nhập các dòng chỉ có mã nhưng chưa có tên học viên.</p><p>Nhật ký thanh toán trường gốc được giữ để đối soát, chưa cộng vào sổ trả trường vì chưa có phân bổ theo hồ sơ và có thông tin mâu thuẫn.</p>`+table(['Ngày / đợt gốc','Nội dung gốc','Số tiền gốc','Người nộp / thụ hưởng','Hình thức ghi gốc'],(state.hungthinhSource.schoolJournal||[]).slice(8).filter(r=>r[8]).map(r=>[esc(r[9]),esc(r[10]),esc(r[11]),esc(r[12]),esc(r[13])])));
 html+=listToolbar('imports',[['category','Hạng bằng',categoryOptions()]]);
 const drafts=(state.importDrafts||[]).filter(d=>d.status==='pending'&&listMatch('imports',[d.lead?.name,d.lead?.externalCode,d.errors?.join(' ')].join(' '),{category:d.lead?.schoolCategory}));
 html+=panel('Danh sách chờ bổ sung — chưa tính KPI; tiền nguồn vẫn được tổng hợp',table(['Học viên','Mã','File / dòng','Lỗi',''],drafts.map(d=>[esc(d.lead.name),esc(displayStudentCode(d.lead)),`${esc(d.filename)} / ${d.row}`,`<span class="error">${d.errors.map(esc).join('<br>')}</span>`,btn('import-edit-draft','Bổ sung',d.id,true)])));
 return html;
}
function resetMapping(){importJob=null;importMapping=columnGuess(importFile.sheets[importSheet].preview[importHeader]||[])}
function wireImport(){
 $('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>6000000)throw Error('File tối đa 6 MB');$('#import-loading').textContent='Đang đọc file…';const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});importFile=await api('import/file',{name:file.name,base64});importSheet=0;importHeader=0;const match=importFile.sheets[0].preview.findIndex(row=>row.some(x=>['hoten','hovaten','tenhocvien'].includes(norm(x))));if(match>=0)importHeader=match;resetMapping();await render()}catch(e){toast(e.message);$('#import-loading').textContent=''}};
 if(!importFile)return;
 $('#import-sheet').onchange=async e=>{importSheet=Number(e.target.value);importHeader=0;resetMapping();await render()};
 $('#import-header').onchange=async e=>{importHeader=Math.max(0,Math.min(39,Number(e.target.value)-1));resetMapping();await render()};
 for(const [id,key]of [['year','year'],['source','source'],['owner','owner'],['school','school'],['date','defaultDate']])$('#import-'+id).onchange=e=>{importConfig[key]=key==='year'?Number(e.target.value):e.target.value;importJob=null};
 document.querySelectorAll('[data-map]').forEach(el=>el.onchange=e=>{importMapping[e.target.dataset.map]=e.target.value;importJob=null});
}
async function importAction(action,id){try{
 if(action==='import-hungthinh'){if(!confirm('Đưa 34 hồ sơ từ bản chụp Google Sheets vào danh sách chờ bổ sung? Không đoán nguồn data, không tạo tài khoản nhân sự và không ghi đè hồ sơ đã có.'))return;const r=await api('import/hungthinh',{});await reload();return toast(`Đã nạp ${r.added} hồ sơ vào danh sách chờ; ${r.skipped} hồ sơ đã có`)}
 if(action==='import-template')return csv('mau-nhap-hoc-vien',Object.values(importColumns),[]);
 if(action==='import-preview'){importJob=await api('import/preview',{fileId:importFile.id,sheet:importSheet,header:importHeader,mapping:importMapping,config:importConfig});await render()}
 if(action==='import-commit'){if(!importJob)return toast('Xem trước lại sau khi thay thông tin');if(!confirm(`Nhập ${importJob.valid} dòng hợp lệ và lưu ${importJob.pending} dòng chờ bổ sung?`))return;const result=await api('import/commit',{jobId:importJob.id});importJob=null;importFile=null;await reload();toast(`Đã nhập ${result.imported} hồ sơ, ${result.pending} dòng chờ bổ sung`)}
 if(action==='import-edit-draft'){
 const d=state.importDrafts.find(d=>d.id===id),fields=Object.entries(importColumns).map(([key,label])=>field(key,label,key==='phone'?'tel':'text',null,['name','phone','cccd','license'].includes(key)));
 fields.push(field('importOwner','Nhân sự phụ trách','text',Object.fromEntries(state.staff.filter(s=>['sale','manager','collaborator'].includes(s.role)).map(s=>[s.id,s.name])),true),field('importSource','Nguồn data','text',{personal:'Cá nhân',company:'Công ty'},true),field('importYear','Năm cho ngày thiếu năm','number',null,true),field('importDate','Ngày ghi nhận nếu không có thu','date'));
 return edit('Bổ sung dòng Excel và nhập hồ sơ',fields,{...d.raw,importOwner:d.lead.owner||'',importSource:d.lead.source||'',importYear:Number(today().slice(0,4)),importDate:d.lead.kpiDate||''},data=>{const raw=Object.fromEntries(Object.keys(importColumns).map(k=>[k,data[k]]));raw.source=data.importSource;return api('import/promote',{id:d.id,raw,config:{owner:data.importOwner,source:data.importSource,year:data.importYear,defaultDate:data.importDate}})});
 }
 }catch(e){toast(e.message)}}

function leadRows(){return filterLeadDirectory(buildLeadDirectory(state.leads,state.importDrafts),{...leadFilters,query:q,status:filter},staffName).filter(l=>{const f=financialFlags(l);return (!leadFilters.waiting||(waitingForOpening(l)?'waiting':'other')===leadFilters.waiting)&&(!leadFilters.due||f.due===leadFilters.due)&&(!leadFilters.tuition||f.tuition===leadFilters.tuition)}).sort((a,b)=>displayStudentCode(a).localeCompare(displayStudentCode(b),'vi',{numeric:true}))}
function lookupStudent(l){const id=l.lead||l.id;return buildLeadDirectory(state.leads,state.importDrafts).find(s=>s.id===id||!!(l.code||l.externalCode)&&s.externalCode===(l.code||l.externalCode))||l}
function studentLabel(l){const s=lookupStudent(l),due=paymentDueState(s.id,state.paymentPlans,today());return `<span class="${due.due?'text-alert':''}">${esc(l.name||s.name)}</span>${due.due?'<br><span class="tag alert">'+(due.overdue?'Quá hạn học phí':'Đến hạn học phí')+'</span>':''}`}
function courseLabel(l){return `<span class="${waitingForOpening(l)?'text-alert':''}">${esc(l.course||'')}</span>`}
function categoryOptions(){return Object.fromEntries([...new Set(buildLeadDirectory(state.leads,state.importDrafts).map(l=>l.schoolCategory).filter(Boolean))].map(v=>[v,v]))}
function courseOptions(){return Object.fromEntries([...new Set(buildLeadDirectory(state.leads,state.importDrafts).map(l=>l.course).filter(Boolean))].map(v=>[v,v]))}
function listToolbar(scope,fields){const f=listFilters[scope]||{};return `<div class="toolbar"><input data-list-scope="${scope}" data-list-key="query" placeholder="Tìm trong danh sách…" value="${esc(f.query||'')}">${fields.map(([key,label,opts])=>`<select aria-label="${label}" data-list-scope="${scope}" data-list-key="${key}"><option value="">${label}: Tất cả</option>${options(opts,f[key])}</select>`).join('')}${btn('list-clear','Xóa lọc',scope,true)}</div>`}
function listMatch(scope,text,values={}){const f=listFilters[scope]||{};return searchMatches(text,f.query||'')&&Object.entries(f).every(([key,value])=>key==='query'||!value||String(values[key]??'')===value)}
function financialFlags(l){const gate=state.examEligibility.find(g=>g.lead===l.id),due=paymentDueState(l.id,state.paymentPlans,today());return {category:l.schoolCategory,course:l.course,due:due.due?'due':'clear',tuition:gate?.eligible?'paid':'owing'}}
function trainingRows(){return buildLeadDirectory(state.leads,state.importDrafts).filter(l=>listMatch('training',[l.name,l.phone,l.studentCode,l.externalCode,l.importStage].join(' '),financialFlags(l)))}
function tuitionComplete(student){
 return Number(student.tuition)>0 && Number(student.remaining)===0 && student.remaining!=null;
}
function loadTuitionChecks(){
 const key='htblx:tuition-checks:'+(user.id||user.username||user.name);
 if(key!==tuitionChecksKey){
  tuitionChecksKey=key;
  tuitionChecks=new Set();
  try{tuitionChecks=new Set(JSON.parse(localStorage.getItem(key)||'[]'))}catch{}
 }
 for(const review of state.tuitionReviews||[]){
  if(review.checked)tuitionChecks.add(review.id);else tuitionChecks.delete(review.id);
 }
}
function tuitionRow(student,cells,action){
 const code=student.code||student.externalCode;
 const key=code?'code:'+code:student.id?'id:'+student.id:'';
 const complete=tuitionComplete(student),checked=!!key&&tuitionChecks.has(key);
 const control=key?`<label class="tuition-check"><input type="checkbox" data-tuition-check="${esc(key)}" aria-label="Đã đối chiếu học phí của ${esc(student.name)}" ${checked?'checked':''}><span>${complete?'HOÀN THÀNH':'Tích đối chiếu'}</span></label>`:complete?tag('HOÀN THÀNH'):'';
 return {className:[complete?'tuition-complete':'',checked?'tuition-checked':''].join(' '),cells:[...cells,control,...(action===undefined?[]:[action])]};
}
function wireTuitionChecks(){
 const boxes=document.querySelectorAll('[data-tuition-check]');
 const keys=new Set(Array.from(boxes,box=>box.dataset.tuitionCheck));
 const counter=$('#tuition-check-count');
 const updateCount=()=>{
  if(counter)counter.textContent='Đã tích '+[...keys].filter(key=>tuitionChecks.has(key)).length+'/'+keys.size+' học viên hiển thị';
 };
 updateCount();
 for(const box of boxes)box.onchange=async()=>{
  const key=box.dataset.tuitionCheck;
  if(fin()){
   box.disabled=true;
   try{
    await api('tuition/review',{key,checked:box.checked});
    state.tuitionReviews=(state.tuitionReviews||[]).filter(review=>review.id!==key);
    state.tuitionReviews.push({id:key,checked:box.checked});
   }catch(error){box.checked=tuitionChecks.has(key);toast(error.message);return}
   finally{box.disabled=false}
  }
  if(box.checked)tuitionChecks.add(key);else tuitionChecks.delete(key);
  try{localStorage.setItem(tuitionChecksKey,JSON.stringify([...tuitionChecks]))}catch{}
  for(const other of boxes){
   if(other.dataset.tuitionCheck!==key)continue;
   other.checked=box.checked;
   other.closest('tr')?.classList.toggle('tuition-checked',box.checked);
  }
  updateCount();
 };
}
function paymentListMatches(l){const s=lookupStudent(l),flags=financialFlags(s);if(l.remaining!==undefined)flags.tuition=tuitionComplete(l)?'paid':'owing';return listMatch('payments',[l.name||s.name,displayStudentCode(l),l.code||s.externalCode,s.phone].join(' '),flags)}
function filteredTasks(){return state.tasks.filter(t=>listMatch('tasks',[t.title,staffName(t.assignee),leadName(t.lead)].join(' '),{status:t.status,assignee:t.assignee,due:t.status!=='done'&&t.due<today()?'overdue':t.status!=='done'&&t.due===today()?'today':''}))}
function filteredStaff(){return state.staff.filter(s=>listMatch('staff',[s.name,roles[s.role]].join(' '),{role:s.role,joining:s.joinDate?'present':'missing'}))}
function filteredAccounts(){return state.users.filter(u=>listMatch('accounts',[u.name,u.username].join(' '),{role:u.role}))}
function schoolRows(){return buildLeadDirectory(state.leads,state.importDrafts).map(l=>({...l,school:l.school||state.schoolName})).filter(l=>listMatch('schools',[l.name,l.studentCode,l.externalCode,l.phone].join(' '),{category:l.schoolCategory}))}
function leadFilterControls(directory){
 const choices=(key,empty=false)=>Object.fromEntries([...(empty?[['__empty','Chưa cập nhật']]:[]),...[...new Set(directory.map(l=>l[key]).filter(Boolean))].sort().map(v=>[v,v])]);
 const defs=[['category','Hạng bằng / gói',choices('schoolCategory')],['course','Khóa học',choices('course',true)],['owner','Nhân sự phụ trách',{__empty:'Chưa phân công',...Object.fromEntries(state.staff.filter(s=>['sale','manager','collaborator'].includes(s.role)).map(s=>[s.id,s.name]))}],['source','Nguồn data',{company:'Công ty',personal:'Cá nhân',__empty:'Chưa xác định'}],['documents','Tình trạng giấy tờ',{complete:'Đủ hồ sơ',incomplete:'Thiếu / chưa đủ',unknown:'Chưa cập nhật'}],['handover','Trạng thái bàn giao',Object.fromEntries(['Chưa bàn giao','Đã gửi trường','Trường yêu cầu bổ sung','Trường đã nhận','Đã bàn giao','Đã hoàn thành'].map(v=>[v,v]))],['stage','Tiến độ học',Object.fromEntries([...new Set(directory.map(l=>l.importStage||l.theory||'Chưa cập nhật'))].sort().map(v=>[v,v]))],['waiting','Khai giảng',{waiting:'Chờ khai giảng',other:'Khác'}],['due','Hạn học phí',{due:'Đến hạn / quá hạn',clear:'Chưa đến hoặc đã đủ'}],['tuition','Thanh toán học phí',{paid:'Đã tất toán',owing:'Còn nợ'}],['missing','Thông tin còn thiếu',{any:'Có thông tin còn thiếu',phone:'Thiếu điện thoại',cccd:'Thiếu / sai CCCD',openingDate:'Thiếu ngày khai giảng',owner:'Chưa phân công',source:'Chưa xác định nguồn'}]];
 return `<section class="panel"><h2>Bộ lọc hồ sơ học viên</h2><div class="grid">${defs.map(([key,label,opts])=>`<div><label>${label}</label><select data-lead-filter="${key}"><option value="">Tất cả</option>${options(opts,leadFilters[key])}</select></div>`).join('')}</div></section>`;
}
function documentKey(l){return (l._pending?'draft:':'lead:')+l.id}
function documentRows(){return buildLeadDirectory(state.leads,state.importDrafts).filter(l=>[l.studentCode,l.externalCode,l.name,l.phone].join(' ').toLowerCase().includes(docQuery.toLowerCase())&&(!docFilter||(l.handover||'Chưa bàn giao')===docFilter))}
function updateDocumentCount(){const rows=documentRows(),keys=rows.map(documentKey);docSelection=new Set([...docSelection].filter(k=>keys.includes(k)));const counter=$('#doc-selected-count');if(counter)counter.textContent=`Đã chọn ${docSelection.size}/${rows.length}`;const all=$('#doc-select-all');if(all){all.checked=keys.length>0&&keys.every(k=>docSelection.has(k));all.indeterminate=docSelection.size>0&&!all.checked}}
function wireDocuments(){
 $('#doc-search').onchange=async e=>{docQuery=e.target.value;docSelection.clear();await render()};$('#doc-filter').onchange=async e=>{docFilter=e.target.value;docSelection.clear();await render()};
 if($('#doc-select-all'))$('#doc-select-all').onchange=e=>{docSelection=e.target.checked?new Set(documentRows().map(documentKey)):new Set();document.querySelectorAll('[data-doc-key]').forEach(box=>box.checked=docSelection.has(box.dataset.docKey));updateDocumentCount()};
 document.querySelectorAll('[data-doc-key]').forEach(box=>box.onchange=e=>{if(e.target.checked)docSelection.add(e.target.dataset.docKey);else docSelection.delete(e.target.dataset.docKey);updateDocumentCount()});updateDocumentCount();
}
function updateDocuments(action,key){
 const rows=documentRows(),keys=action==='documents-all'?rows.map(documentKey):action==='documents-one'?[key]:[...docSelection].filter(k=>rows.some(l=>documentKey(l)===k));
 if(!keys.length)return toast('Chọn ít nhất một hồ sơ');
 return edit(`Cập nhật bàn giao ${keys.length} hồ sơ`,[field('status','Trạng thái bàn giao','text',{'Đã bàn giao':'Đã bàn giao','Đã hoàn thành':'Đã hoàn thành bàn giao hồ sơ'},true),field('date','Ngày bàn giao thực tế','date',null,true),field('note','Ghi chú chung (nếu có)','textarea')],{status:'Đã bàn giao',date:today()},async d=>{const result=await api('documents/bulk',{keys,status:d.status,date:d.date,note:d.note});docSelection.clear();toast(`Đã cập nhật ${result.updated} hồ sơ`);return result});
}

try{user=await api("me");await reload()}catch{await auth()}
